  tool_indexnow_desc: 'IndexNow: buat kunci, cek .txt, kirim URL ke Bing.',
  tool_indexnow_description:
    'Buat kunci IndexNow, unduh file .txt, periksa file live cocok, lalu kirim URL yang berubah ke Bing dan mesin peserta. Ikuti langkah, baca tabel status (200 vs 202) dan contoh JSON — memberi tahu perubahan bukan jaminan indeks.',
  tool_indexnow_disclaimer:
    'Educational webmaster tool only. IndexNow does not guarantee crawl, index, or ranking outcomes. Prefer official IndexNow and Bing docs when policies change.',
  tool_indexnow_download: 'Unduh .txt',
  tool_indexnow_endpoint_bing: 'Bing direct',
  tool_indexnow_endpoint_indexnow: 'api.indexnow.org (shared)',
