  tool_text_diff_sample_a: 'Halo dunia\nbaris dua\nbaris tiga',
  tool_text_diff_sample_b: 'Halo teman\nbaris dua\nbaris tiga',
  tool_text_diff_summary: '{added} ditambah, {removed} dihapus',
  tool_text_diff_swap: 'Tukar sisi',
